   if(!$customerId){$pdo->prepare("INSERT INTO customers (type,name,email,phone,status,created_at) VALUES ('individual',?,?,?,'active',NOW())")->execute([$name,$email,$phone?:null]);$customerId=(int)$pdo->lastInsertId();}
   $grand=$subtotal+$taxTotal;$tmp='TMP-'.bin2hex(random_bytes(8));$notes="Web mağazası siparişi
Teslimat adresi: ".$address;
