   $orderId=(int)$pdo->lastInsertId();$number='WEB-'.date('Y').'-'.str_pad((string)$orderId,6,'0',STR_PAD_LEFT);$pdo->prepare('UPDATE orders SET order_number=? WHERE id=?')->execute([$number,$orderId]);
   $ins=$pdo->prepare('INSERT INTO order_items (order_id,product_id,product_name,sku,quantity,unit_price,tax_rate,line_subtotal,line_tax,line_total,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,NOW())');
   foreach($items as [$p,$qty,$price,$rate,$line,$tax,$total])$ins->execute([$orderId,$p['id'],$p['name'],$p['sku'],$qty,$price,$rate,$line,$tax,$total]);
   $pdo->prepare('INSERT INTO order_status_history (order_id,user_id,from_status,to_status,note,created_at) VALUES (?,NULL,NULL,?,?,NOW())')->execute([$orderId,'draft','Web mağazasından sipariş alındı']);
   $paytrToken=null;
   if($paymentMethod==='paytr'){
