   header('Location: store.php?action=thankyou');exit;
  }
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('KodVadAll storefront: '.$e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'İşleminiz tamamlanamadı.';}
